import{_ as e,c as t,o as a,f as n}from"./chunks/framework.BOAZPCR7.js";const m=JSON.parse('{"title":"Defining the molecular interaction between influenza hemagglutinin and MHC-II","description":"","frontmatter":{"layout":"post","title":"Defining the molecular interaction between influenza hemagglutinin and MHC-II","date":"2026-07-23T00:00:00.000Z","author":"Jesse Bloom","head":[["link",{"rel":"canonical","href":"https://jbloomlab.org/posts/2026-07-23_ha_mhcii.html"}]]},"headers":[],"relativePath":"posts/2026-07-23_ha_mhcii.md","filePath":"posts/2026-07-23_ha_mhcii.md"}'),o={name:"posts/2026-07-23_ha_mhcii.md"},r=n('<p>We just <a href="https://doi.org/10.64898/2026.07.17.738765" target="_blank" rel="noreferrer">posted to bioRxiv</a> a new study led by Bernadeta Dadonaite that uses a novel combination of deep mutational scanning and cryo-EM to show how influenza HA interacts with MHC-II. Many important questions remain about how this interaction evolves and its biological role, and determining its structural basis is a first step towards answering those questions.</p><hr><p>Influenza hemagglutinin (HA) has long been known to use sialic acid as a receptor, but about 7 years ago it was <a href="https://www.nature.com/articles/s41586-019-0955-3" target="_blank" rel="noreferrer">shown</a> that some highly diverged bat influenza HAs use MHC-II as their entry receptor. Subsequently it was shown some H2 and H3 HAs could also use MHC-II. However, the structural basis of this interaction has remained unclear.</p><p>We first showed that many H5 HAs can bind to avian MHC-II, and then used pseudovirus deep mutational scanning to measure how all mutations to a H5 HA affect entry and binding to tufted duck MHC-II. This work enabled us to functionally define a surface on the HA head that binds MHC-II. We then used identification of mutations that increase HA binding to tufted duck MHC-II to solve a cryo-EM structure of the complex. We also measured how MHC-II mutations affect the interaction.</p><p>Our <a href="https://doi.org/10.64898/2026.07.17.738765" target="_blank" rel="noreferrer">preprint</a> also has lots of other interesting findings related to HA&#39;s ability to interact with MHC-II and how this varies across HAs of many subtypes and MHC-II alleles.</p><p>In addition to reading the preprint, for more details see:</p><ul><li><a href="https://bsky.app/profile/jbloomlab.bsky.social/post/3mrdg5udgvk2j" target="_blank" rel="noreferrer">This Bluesky thread</a>, which can be read more easily in <a href="https://skywriter.blue/pages/jbloomlab.bsky.social/post/3mrdg5udgvk2j" target="_blank" rel="noreferrer">threaded form here</a>.</li><li><a href="https://x.com/jbloom_lab/status/2080358310562365796" target="_blank" rel="noreferrer">This X thread</a></li></ul><p>To access and view the data, see the following links: <a href="https://dms-vep.org/Flu-H5N1-American-Wigeon-2021-HA-tufted-duck-MHCII-DMS/" target="_blank" rel="noreferrer">https://dms-vep.org/Flu-H5N1-American-Wigeon-2021-HA-tufted-duck-MHCII-DMS/</a>.</p>',8),s=[r];function i(l,h,d,c,u,p){return a(),t("div",null,s)}const _=e(o,[["render",i]]);export{m as __pageData,_ as default};
